import csv,json,statistics
from common import ROOT,atomic_json

def main():
 r=json.loads((ROOT/'metrics/final_results.json').read_text());assert r['completed'];cfg=json.loads((ROOT/'config.json').read_text());train=[json.loads(s) for s in (ROOT/'logs/train.jsonl').read_text().splitlines()];assert [x['step'] for x in train]==list(range(1,r['training']['steps']+1));assert json.loads((ROOT/'metrics/resume_verification.json').read_text())['all135_native_tensors_bitwise_equal']
 stats=dict(completed_steps=len(train),unique_source_examples=len({s for x in train for s in x['sample_ids']}),input_tokens=sum(x['input_tokens'] for x in train),first64_mean_loss=statistics.mean(x['loss'] for x in train[:64]),last64_mean_loss=statistics.mean(x['loss'] for x in train[-64:]),updated_parameters=cfg['trainable_parameters'],total_parameters=cfg['parameters']);atomic_json(ROOT/'metrics/run_statistics.json',stats)
 with (ROOT/'metrics/training_loss.csv').open('w',newline='') as f:
  fields=['step','loss','openbookqa_choice_nll','piqa_choice_nll','alpaca_nll','grad_norm','lr','seconds','input_tokens'];w=csv.DictWriter(f,fields);w.writeheader();w.writerows({k:x[k] for k in fields} for x in train)
 base=json.loads((ROOT/'metrics/parent_EXT2_balanced_dev_summary.json').read_text());step=r['selection']['best_step'];dev=base if step==0 else json.loads((ROOT/f'metrics/step_{step:04d}_balanced_dev_summary.json').read_text());c=r['comparisons']['parent_EXT2'];ci=c['stratified_paired_bootstrap95'];s=r['summaries'];table=[]
 for task in ['openbookqa','piqa','arc_challenge']:
  nums=[s[a]['by_task'][task]['label_correct'] for a in ['original_EXT256','parent_EXT2','selected_EXT3']];gens=[s[a]['by_task'][task]['generation_correct'] for a in ['original_EXT256','parent_EXT2','selected_EXT3']];table.append(f'| {task} | {nums[0]}/128 | {nums[1]}/128 | {nums[2]}/128 | {gens[0]} → {gens[1]} → {gens[2]} /128 |')
 prior='; '.join(f"{task}: {counts}" for task,counts in r['prediction_counts']['selected_EXT3'].items())
 verdict='подтверждён на этом узком pilot' if r['registered_improvement_criterion_met'] else 'не подтверждён'
 text=f'''# FlyGraph EXT3: проверка позиционного смещения\n\nВыполнено **{len(train)} новых шагов** из запланированных768, {stats['unique_source_examples']} уникальных исходных записей, {stats['input_tokens']:,} входных токенов. Причина завершения: `{r['training']['stop_reason']}`; полный план выполнен: **{r['training']['completed_fixed_step_count']}**. Время обучения/dev/checkpoint: {r['training']['wall_seconds']/60:.2f} минуты. Это дообучение реального EXT2 checkpoint3584 с новым AdamW; модель100028328 параметров, обновлялись13391640 параметров последних двух блоков и финальной нормализации. Остальные веса и tokenizer сохранены. CPU4, RAM16GiB, GPU нет.\n\n**Рост качества относительно EXT2 {verdict}.** Средняя разница точности выбора метки **{100*c['mean_label_difference']:+.2f} п.п.**,95% ДИ **[{100*ci[0]:+.2f}; {100*ci[1]:+.2f}]**. Критерий зафиксирован до обучения: положительный95% интервал, положительное направление минимум на2 задачах и отсутствие ухудшения Alpaca NLL.\n\n| Новый внешний test | Исходный EXT256 | EXT2 | EXT3 selected | Свободная генерация: EXT256 → EXT2 → EXT3 |\n|---|---:|---:|---:|---:|\n{chr(10).join(table)}\n\nAlpaca held-out64 NLL: **{s['original_EXT256']['alpaca_nll']:.4f} → {s['parent_EXT2']['alpaca_nll']:.4f} → {s['selected_EXT3']['alpaca_nll']:.4f}**. Выбран новый шаг **{step}** исключительно по новому dev. Разметка частот меток0=A,1=B,2=C,3=D: {prior}. Полные результаты и парные bootstrap10000 повторов, seed20261026, сохранены в JSON/CSV; все384 сырых MCQ ответа каждой из3 моделей сохранены.\n\n**Превосходство над Qwen3.5-0.8B и MiniCPM-V-4.7-1B не установлено.** Обе точные модели не измерены: повторная разрешённая проверка официального HuggingFace CONNECT2026-10-25 вернула403. Обходов, подмен моделей, платных API/ресурсов или чисел из model cards нет. Нулевые значения не приписываются отсутствующим baseline.\n\n## Гипотеза и диагностика\n\nНа новом dev исходный EXT2 сохранял выбранное содержание ответа при всех циклических перестановках только в **{base['source_option_invariant_questions']}/{base['n_unique_questions']}** вопросах. После выбранного EXT3: **{dev['source_option_invariant_questions']}/{dev['n_unique_questions']}**. Это поддерживает диагноз позиционного смещения; сама инвариантность ещё не доказывает правильность ответа.\n\nКаждый update содержит все4 циклических порядка одного опубликованного OpenBookQA вопроса и оба порядка одного PIQA вопроса: целевые буквы внутри каждого набора точно сбалансированы. Используется cross-entropy среди допустимых меток, без доминирования EOS. Вес loss:0.4 OpenBookQA,0.4 PIQA,0.2 Alpaca assistant/EOS. Нет придуманных вопросов, вариантов или gold-ответов: переставлены существующие варианты и точно перенесён индекс правильного ответа. Ограничение обучения верхними двумя блоками снижает стоимость эксперимента и сохраняет нижние представления; это не полноразмерное переобучение всех100M весов.\n\nВыбор checkpoint: минимум среднего normalized choice NLL на32 новых OpenBookQA и32 PIQA dev с полным набором циклических порядков (192 представления). ARC dev не участвовал в выборе. Parent разрешён как step0. Формат и рост энтропии сами по себе не являются успехом. После открытия test обучение/выбор/протокол не менялись. Test original order, одинаковые prompts и greedy16 новых токенов по полному словарю с EOS у всех моделей. Ranking использует log p одной метки; ties по порядку вариантов, greedy ties по token ID.\n\n## Источники и независимость\n\nTrain: по768 исходных OpenBookQA/PIQA/Alpaca из прежнего EXT2 training; повторное использование train явно разрешено, исключены новые holdouts. Новый MCQ dev96 и test384 исключают прежние MCQ train/dev/test и ARC128 по нормализованному stem. Новые Alpaca dev32/test64 исключают прежние EXT/EXT2 train/dev/test по ID и нормализованным инструкциям. PIQA test — новый зарезервированный размеченный validation subset, не hidden official test. OpenBookQA и ARC-Challenge используют официальные test. Неизвестная историческая pretraining contamination и перефразы не исключаются. Проверки известных пересечений: `metrics/overlap_audit.json`.\n\nФиксированные источники: [OpenCompass release0.2.2.rc1](https://github.com/open-compass/opencompass/releases/tag/0.2.2.rc1), [OpenBookQA](https://github.com/allenai/OpenBookQA), [PIQA](https://github.com/ybisk/ybisk.github.io/tree/master/piqa), [ARC](https://huggingface.co/datasets/allenai/ai2_arc), [Alpaca revision761dc5b](https://github.com/tatsu-lab/stanford_alpaca/tree/761dc5bfbdeeffa89b8bff5d038781a4055f796a). SHA, seed20261025, original IDs и записи — `data/manifest.json` и JSONL. Лицензии: Apache2, AFL3, CC-BY-SA4, CC-BY-NC4 соответственно; research-веса сохраняют некоммерческие ограничения Alpaca.\n\n## Сохранность и ограничения\n\nNative FP32 weights и AdamW, CPU BF16 autocast, FP32 delta state. AdamW5e-5, warmup32, cosine→10%, betas(0.9,0.95), WD0.01, clip1. Checkpoint64, атомарная запись/strict reload; избыточные recovery pruned только после подтверждённого преемника, hash receipts сохранены. Native resume из step64 воспроизвёл шаги65–128 с точным совпадением64 losses/gradient norms и всех135 тензоров. Родительские веса сохранены в предыдущем опубликованном EXT2; новые final/selected bytes и optimizer/RNG/config/data identity сохранены без квантования, части<90MB. Статус push/readback проверяется отдельно по `PUBLICATION.json`; этот отчёт сам по себе не подтверждает публикацию.\n\nОдин seed и три небольших английских MCQ набора не оценивают универсальное рассуждение, русский язык, код, память или мультимодальность. Сырые примеры Alpaca не отбирались по качеству: первые4 test-записи, одинаковый бюджет32 токена. Отрицательные результаты сохранены.\n'''
 (ROOT/'REPORT_RU.md').write_text(text)
 import matplotlib;matplotlib.use('Agg');import matplotlib.pyplot as plt
 fig,ax=plt.subplots(figsize=(8,3.5));ax.plot([x['step'] for x in train],[x['loss'] for x in train],lw=.8);ax.set(xlabel='New completed updates',ylabel='Registered weighted loss',title='EXT3 counterbalanced choice discrimination');fig.tight_layout();fig.savefig(ROOT/'metrics/training_loss.png',dpi=150);plt.close(fig)
 print('Report generated from completed measurements',flush=True)
if __name__=='__main__':main()
